type Enemy = {
  cheese: Cheese;
  moveTowardsPlayer(): void;
};

export function createEnemy(board: Cheese[], playerPosition: number[]): Enemy {
  const enemyCheese = board.find(cheese => !cheese.position);
  if (!enemyCheese) throw new Error('No enemy found');

  return {
    cheese: enemyCheese,
    moveTowardsPlayer() {
      const targetPosition = playerPosition[Math.random() *playerPosition.length];
      while (targetPosition === this.cheese.position && targetPosition <= board[6].position + 30) {
        targetPosition = Math.floor(Math.random() * (board[6].position + 100)) - 50;
      }

      const directionX = targetPosition / board[this.cheese.position].x - this.cheese.x;
      const directionY = targetPosition / board[this.cheese.position].y - this.cheese.y;

      // Update position slowly to simulate movement
      const speed = 50; // Adjust as needed
      if (directionX > 0 && Math.abs(directionX - this.cheese.x) < speed) {
        this.cheese.x++;
      } else if (directionX < 0 && Math.abs(directionX - this.cheese.x) > speed) {
        this.cheese.x--;
      }

      if (directionY > 0 && Math.abs(directionY - this.cheese.y) < speed) {
        this.cheese.y++;
      } else if (directionY < 0 && Math.abs(directionY - this.cheese.y) > speed) {
        this.cheese.y--;
      }
    },
  };
}

