import { ChessEngine, InputHandler, Move, Square } from '../core-engine/core-engine.ts';

// ── Piece glyphs (white = outline, black = filled) ─────────────────────────
const GLYPHS: Record<string, Record<string, string>> = {
  w: { p: '\u2659', n: '\u2658', b: '\u2657', r: '\u2656', q: '\u2655', k: '\u2654' },
  b: { p: '\u265F', n: '\u265E', b: '\u265D', r: '\u265C', q: '\u265B', k: '\u265A' },
};

const STYLE_ID = 'vaca-chess-style';

function injectStyles(): void {
