.vaca-chess .sq { width: 56px; height: 56px; display: flex; align-items: center; justify-content: center; font-size: 34px; cursor: pointer; position: relative; }
.vaca-chess .sq.light { background: #f0d9b5; }
.vaca-chess .sq.dark { background: #b58863; }
.vaca-chess .sq.selected { outline: 3px solid #4a9eff; outline-offset: -3px; }
.vaca-chess .sq.hint::after { content: ''; position: absolute; width: 16px; height: 16px; border-radius: 50%; background: rgba(74,158,255,0.55); }
.vaca-chess .sq.hint.capture::after { width: 100%; height: 100%; border-radius: 50%; border: 4px solid rgba(239,68,68,0.8); background: transparent; box-sizing: border-box; }
.vaca-chess .piece.w { color: #fff; text-shadow: 0 1px 2px rgba(0,0,0,0.8); }
.vaca-chess .piece.b { color: #111; text-shadow: 0 1px 2px rgba(255,255,255,0.4); }
.vaca-chess .controls { display: flex; gap: 8px; justify-content: center; margin: 10px 0; }
.vaca-chess .controls button { padding: 6px 14px; border-radius: 6px; border: 1px solid #4a9eff; background: #1e293b; color: #e0e0e0; cursor: pointer; font-size: 13px; }
.vaca-chess .controls button:hover { background: #334155; }
.vaca-chess .movelog { max-height: 120px; overflow-y: auto; background: #0f172a; border: 1px solid #334155; border-radius: 6px; padding: 6px 10px; font-size: 12px; line-height: 1.5; }
.vaca-chess canvas { display: block; margin: 0 auto; border: 1px solid #334155; border-radius: 6px; background: #1e293b; }
