export function initializeGameState(): GameState {
  const board: string[][] = [
    ['r', 'n', 'b', 'q', 'k', 'b', 'n', 'r'],
    ['p', 'p', 'p', 'p', 'p', 'p', 'p', 'p'],
    ['.', '.', '.', '.', '.', '.', '.', '.'],
    ['.', '.', '.', '.', '.', '.', '.', '.'],
    ['.', '.', '.', '.', '.', '.', '.', '.'],
    ['.', '.', '.', '.', '.', '.', '.', '.'],
    ['P', 'P', 'P', 'P', 'P', 'P', 'P', 'P'],
    ['R', 'N', 'B', 'Q', 'K', 'B', 'N', 'R']
  ];
  return { board, currentPlayer: 'white', lastMove: null };
}

export function makeMove(state: GameState, from: string, to: string): GameState {
  const [fromFile, fromRank] = from.split('');
  const [toFile, toRank] = to.split('');
  const fromRow = parseInt(fromRank) - 1;
  const fromCol = 'abcdefgh'.indexOf(fromFile);
  const toRow = parseInt(toRank) - 1;
  const toCol = 'abcdefgh'.indexOf(toFile);

  const piece = state.board[fromRow][fromCol];
  if (!piece) {
    throw new Error('No piece to move');
  }

  if (piece.toLowerCase() !== 'p' && piece.toLowerCase() !== 'n' && piece.toLowerCase() !== 'b' && piece.toLowerCase() !== 'r' && piece.toLowerCase() !== 'q' && piece.toLowerCase() !== 'k') {
    throw new Error('Invalid piece');
  }

  if (piece === '.' || piece === '') {
    throw new Error('Empty square');
  }

  state.board[toRow][toCol] = piece;
  state.board[fromRow][fromCol] = '.';
  state.lastMove = { from, to };
  state.currentPlayer = state.currentPlayer === 'white' ? 'black' : 'white';

  return state;
}

export function undoMove(state: GameState): GameState {
  if (!state.lastMove) {
    throw new Error('No move to undo');
  }

  const { from, to } = state.lastMove;
  const [fromFile, fromRank] = from.split('');
  const [toFile, toRank] = to.split('');
  const fromRow = parseInt(fromRank) - 1;
  const fromCol = 'abcdefgh'.indexOf(fromFile);
  const toRow = parseInt(toRank) - 1;
  const toCol = 'abcdefgh'.indexOf(toFile);

  const piece = state.board[toRow][toCol];
  if (!piece) {
    throw new Error('No piece to undo');
  }

  state.board[fromRow][fromCol] = piece;
  state.board[toRow][toCol] = '.';
  state.lastMove = null;
  state.currentPlayer = state.currentPlayer === 'white' ? 'black' : 'white';

  return state;
}

export function resetGame(state: GameState): GameState {
  return initializeGameState();
}

